
.generation-recovery {
  margin: 14px 0;
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--semantic-warning) 40%, var(--line-subtle));
  border-radius: 6px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--semantic-warning) 6%, var(--surface-inset));
  font-size: 13px;
  line-height: 1.7;
}
p {
  margin: 0;
}
p > i {
  color: var(--semantic-warning);
}
.recovery-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
button {
  min-height: 34px;
  padding: 6px 12px;
  border: 1px solid var(--line-strong);
  border-radius: 5px;
  background: var(--surface-inset);
  color: var(--gold);
  cursor: pointer;
}
button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
details {
  margin-top: 8px;
}
summary {
  cursor: pointer;
}
pre {
  max-height: 240px;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: inherit;
}
