
.story-reader {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  isolation: isolate;
  background: var(--reading-surface);
  box-shadow: inset 0 0 70px color-mix(in srgb, var(--stage-shadow) 18%, transparent);
}

.story-reader::before,
.story-reader::after {
  content: '';
  position: absolute;
  z-index: 0;
  pointer-events: none;
}
.story-reader::before {
  inset: 0;
  background: var(--reading-material);
  opacity: 0.9;
}
.story-reader::after {
  top: 18px;
  bottom: 18px;
  left: 14px;
  width: 1px;
  background: linear-gradient(transparent, var(--line-strong) 18%, var(--line-subtle) 82%, transparent);
  opacity: 0.46;
}
.story-reader > * {
  position: relative;
  z-index: 1;
}

.turn-context-bar {
  flex-shrink: 0;
  min-width: 0;
  min-height: 36px;
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  border-bottom: 1px solid var(--line-subtle);
  background: color-mix(in srgb, var(--surface-inset) 68%, transparent);
}

.reasoning-rail {
  width: 100%;
  min-width: 0;
  display: flex;
  justify-content: center;
}

.story-inline-context,
.inline-preset-reasoning {
  width: min(100%, var(--reading-measure));
  min-width: 0;
  margin-inline: auto;
}

.reasoning-inline-context,
.inline-preset-reasoning {
  margin-bottom: clamp(24px, 4vh, 42px);
}

.inline-context-detail {
  margin-top: 12px;
}

.reasoning-inline-detail {
  min-width: 0;
}

.variable-inline-context {
  margin-top: clamp(28px, 5vh, 52px);
  padding-top: 14px;
  border-top: 1px solid var(--line-subtle);
}

.variable-inline-trigger {
  min-height: 34px !important;
  padding: 4px 12px !important;
  flex-wrap: wrap;
  border: 1px solid var(--line-subtle) !important;
  border-radius: 999px !important;
  background: color-mix(in srgb, var(--surface-inset) 82%, transparent) !important;
}

.variable-inline-pills {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
}

.variable-inline-pill {
  padding: 2px 8px;
  border: 1px solid color-mix(in srgb, var(--jade) 34%, var(--line-subtle));
  border-radius: 999px;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 10%, var(--surface-inset));
  font-size: 10px;
  font-style: normal;
  font-weight: 550;
  white-space: nowrap;
}

.variable-inline-trigger:hover,
.variable-inline-trigger[aria-expanded='true'] {
  border-color: var(--line-strong) !important;
  background: var(--button-active) !important;
}

.variable-inline-detail {
  padding: 14px;
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
  background: color-mix(in srgb, var(--surface-inset) 78%, transparent);
}

.turn-prompt-trigger,
.reasoning-trigger,
.variable-trigger {
  min-width: 0;
  min-height: 36px;
  border: 0;
  border-radius: 0;
  color: var(--text-secondary);
  background: transparent;
  cursor: pointer;
  font: inherit;
  font-size: 11px;
}

.turn-prompt-trigger {
  flex: 1;
  padding: 7px 14px 7px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  text-align: left;
}

.turn-prompt-edit {
  min-width: 70px;
  padding: 0 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 0;
  border-left: 1px solid var(--line-subtle);
  color: var(--gold-soft);
  background: transparent;
  font-size: 10px;
  cursor: pointer;
}

.turn-prompt-edit:hover:not(:disabled) {
  color: var(--gold);
  background: var(--button-hover);
}

.turn-prompt-edit:disabled {
  opacity: 0.34;
  cursor: not-allowed;
}

.turn-prompt-trigger > i {
  flex: none;
  color: var(--jade);
}
.turn-context-label {
  flex: none;
  color: var(--text-accent);
}
.turn-prompt-preview {
  min-width: 0;
  overflow: hidden;
  color: var(--text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reasoning-trigger,
.variable-trigger {
  flex: none;
  padding: 7px 14px;
  display: flex;
  align-items: center;
  gap: 7px;
  border-left: 1px solid var(--line-subtle);
}

.reasoning-trigger {
  position: relative;
  width: min(100%, 1120px);
  min-height: 48px;
  padding: 5px 13px 5px 5px;
  gap: 11px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--jade) 42%, var(--line-subtle));
  border-radius: 8px;
  background:
    radial-gradient(circle at 4% 50%, color-mix(in srgb, var(--jade) 16%, transparent), transparent 20%),
    repeating-linear-gradient(90deg, transparent 0 52px, color-mix(in srgb, var(--jade) 3%, transparent) 53px 54px),
    linear-gradient(110deg, color-mix(in srgb, var(--surface-raised) 94%, transparent), var(--surface-inset));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--gold) 7%, transparent),
    inset 0 -14px 30px color-mix(in srgb, var(--stage-shadow) 10%, transparent),
    0 7px 22px color-mix(in srgb, var(--stage-shadow) 28%, transparent);
  isolation: isolate;
}
.reasoning-trigger::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 3px;
  border: 1px solid color-mix(in srgb, var(--gold) 12%, transparent);
  border-radius: 5px;
  background: linear-gradient(
    105deg,
    transparent 18%,
    color-mix(in srgb, var(--gold) 8%, transparent),
    transparent 72%
  );
  opacity: 0.72;
  transition: opacity 0.2s ease;
  pointer-events: none;
}
.reasoning-trigger::after {
  content: '✦';
  position: absolute;
  right: 54px;
  bottom: -8px;
  color: color-mix(in srgb, var(--gold) 18%, transparent);
  font-size: 25px;
  line-height: 1;
  transform: rotate(22deg);
  pointer-events: none;
}
.reasoning-trigger-glyph {
  position: relative;
  width: 36px;
  height: 36px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--jade) 50%, transparent);
  border-radius: 50%;
  color: var(--jade);
  background: color-mix(in srgb, var(--surface-inset) 76%, transparent);
  box-shadow:
    inset 0 0 0 3px color-mix(in srgb, var(--jade) 5%, transparent),
    0 0 16px color-mix(in srgb, var(--jade) 13%, transparent);
}
.reasoning-trigger-glyph::after {
  content: '';
  position: absolute;
  inset: -4px;
  border: 1px dashed color-mix(in srgb, var(--jade) 22%, transparent);
  border-radius: 50%;
}
.reasoning-title {
  min-width: 116px;
  display: grid;
  gap: 1px;
  text-align: left;
}
.reasoning-title strong {
  color: var(--text-accent);
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;
  font-weight: 600;
  font-size: 12px;
  letter-spacing: 0.14em;
}
.reasoning-title small {
  color: color-mix(in srgb, var(--text-secondary) 82%, transparent);
  font-size: 8px;
  letter-spacing: 0.08em;
  white-space: nowrap;
}
.reasoning-ornament {
  min-width: 40px;
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  color: color-mix(in srgb, var(--gold) 50%, transparent);
}
.reasoning-ornament i {
  height: 1px;
  flex: 1;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--jade) 34%, transparent),
    color-mix(in srgb, var(--gold) 42%, transparent)
  );
}
.reasoning-ornament i:last-child {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--gold) 42%, transparent),
    color-mix(in srgb, var(--jade) 34%, transparent),
    transparent
  );
}
.reasoning-ornament b {
  font-size: 9px;
  font-weight: 400;
}
.variable-trigger > i:first-child {
  color: var(--gold);
}
.variable-count {
  color: var(--gold-soft);
  font-size: 10px;
  white-space: nowrap;
}
.variable-trigger.has-error > i:first-child,
.variable-trigger.has-error .variable-count {
  color: var(--semantic-danger);
}
.turn-prompt-trigger:hover,
.reasoning-trigger:hover,
.variable-trigger:hover,
.turn-prompt-trigger[aria-expanded='true'],
.reasoning-trigger[aria-expanded='true'],
.variable-trigger[aria-expanded='true'] {
  color: var(--text-primary);
  background: color-mix(in srgb, var(--button-hover) 74%, transparent);
}
.reasoning-trigger:hover::before,
.reasoning-trigger[aria-expanded='true']::before {
  opacity: 1;
}
.reasoning-trigger[aria-expanded='true'] {
  border-color: color-mix(in srgb, var(--gold) 52%, var(--line-strong));
  background:
    radial-gradient(circle at 16% 0%, color-mix(in srgb, var(--gold) 18%, transparent), transparent 46%),
    linear-gradient(110deg, color-mix(in srgb, var(--button-active) 84%, transparent), var(--surface-inset));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--gold) 10%, transparent),
    0 0 18px color-mix(in srgb, var(--accent-glow) 34%, transparent);
}
.reasoning-trigger[aria-expanded='true'] .reasoning-trigger-glyph {
  color: var(--gold);
  border-color: color-mix(in srgb, var(--gold) 52%, transparent);
  box-shadow: 0 0 14px color-mix(in srgb, var(--accent-glow) 42%, transparent);
}

.context-chevron {
  color: var(--text-secondary) !important;
  font-size: 9px;
  transition: transform 0.18s ease;
}
.reasoning-trigger[aria-expanded='true'] .context-chevron,
.variable-trigger[aria-expanded='true'] .context-chevron {
  transform: rotate(180deg);
}

.context-scrim {
  position: absolute !important;
  z-index: 4 !important;
  inset: 36px 0 0;
  width: 100%;
  border: 0;
  background: color-mix(in srgb, var(--stage-shadow) 28%, transparent);
  cursor: default;
}

.context-popover {
  position: absolute !important;
  z-index: 5 !important;
  top: 46px;
  left: clamp(12px, 3vw, 36px);
  right: clamp(12px, 3vw, 36px);
  max-height: min(46vh, 360px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 96%, transparent);
  box-shadow:
    0 18px 54px var(--stage-shadow),
    inset 0 0 0 1px var(--line-subtle);
}

.context-popover-header {
  min-height: 40px;
  flex: none;
  padding: 0 10px 0 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-bottom: 1px solid var(--line-subtle);
  color: var(--text-accent);
  font-size: 12px;
}
.context-popover-header > span:first-child {
  display: flex;
  align-items: center;
  gap: 7px;
}
.context-popover-header > span:first-child i {
  color: var(--jade);
}
.context-popover-time {
  margin-left: auto;
  color: var(--gold-soft);
  font-size: 10px;
}
.context-popover-header button {
  width: 30px;
  height: 30px;
  margin-left: auto;
  border: 0;
  color: var(--text-secondary);
  background: transparent;
  cursor: pointer;
}
.context-popover-time + button {
  margin-left: 0;
}
.context-popover-header button:hover {
  color: var(--text-primary);
}

.context-popover-copy {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior-y: contain;
  touch-action: pan-y pinch-zoom;
  -webkit-overflow-scrolling: touch;
  padding: 16px 18px 18px;
  color: var(--text-primary);
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;
  font-size: 13px;
  line-height: 1.85;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}
.context-popover-copy :deep(p) {
  margin: 0 0 0.9em;
}
.context-popover-copy :deep(p:last-child) {
  margin-bottom: 0;
}

.variable-popover {
  max-height: min(64vh, 520px);
}
.variable-diagnostics {
  min-height: 0;
  overflow-y: auto;
  padding: 14px;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}

.variable-analysis {
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line-subtle);
  border-left: 2px solid var(--gold);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
}
.variable-analysis h3 {
  margin: 0 0 9px;
  color: var(--gold-soft);
  font-size: 11px;
  font-weight: 600;
}
.analysis-segments {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.analysis-segments span {
  padding: 4px 8px;
  border: 1px solid var(--line-subtle);
  border-radius: 999px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 70%, transparent);
  font-size: 11px;
  line-height: 1.45;
}

.variable-overview {
  min-height: 32px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-secondary);
  font-size: 11px;
}
.variable-overview > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-accent);
}
.variable-overview > span:first-child i {
  color: var(--jade);
}
.variable-overview strong {
  color: var(--gold-soft);
  font-weight: 600;
}
.diagnostic-state {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.diagnostic-state.valid {
  color: var(--semantic-success);
}
.diagnostic-state.receiving {
  color: var(--jade);
}
.diagnostic-state.invalid {
  color: var(--semantic-danger);
}

.variable-operation-list {
  margin: 0;
  padding: 0;
  display: grid;
  gap: 7px;
  list-style: none;
}
.variable-operation {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--line-subtle);
  background: color-mix(in srgb, var(--surface-inset) 58%, transparent);
}
.operation-heading {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.operation-index {
  width: 20px;
  height: 20px;
  flex: none;
  display: inline-grid;
  place-items: center;
  border: 1px solid var(--line-subtle);
  border-radius: 50%;
  color: var(--text-secondary);
  font-size: 9px;
}
.operation-kind {
  min-width: 34px;
  flex: none;
  color: var(--gold-soft);
  font-size: 10px;
  text-align: center;
}
.operation-kind.op-delta {
  color: var(--jade);
}
.operation-kind.op-remove {
  color: var(--semantic-danger);
}
.operation-kind.op-insert,
.operation-kind.op-add {
  color: var(--semantic-success);
}
.operation-heading code {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--text-primary);
  font-family: 'Microsoft YaHei UI', system-ui, sans-serif;
  font-size: 11px;
}
.variable-operation pre,
.raw-patch pre {
  margin: 8px 0 0 28px;
  padding: 8px 10px;
  overflow-x: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  border-left: 1px solid var(--line-strong);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-raised) 72%, transparent);
  font:
    11px/1.6 ui-monospace,
    SFMono-Regular,
    Consolas,
    monospace;
}
.operation-from,
.operation-empty {
  margin: 7px 0 0 28px;
  color: var(--text-secondary);
  font-size: 10px;
}
.variable-empty {
  padding: 22px;
  color: var(--text-secondary);
  text-align: center;
  font-size: 11px;
}
.diagnostic-error {
  margin-top: 10px;
  padding: 9px 11px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 55%, var(--line-subtle));
  color: var(--semantic-danger);
  background: color-mix(in srgb, var(--semantic-danger) 8%, transparent);
  font-size: 11px;
}
.raw-patch {
  margin-top: 10px;
  border-top: 1px solid var(--line-subtle);
}
.raw-patch summary {
  padding: 10px 2px 0;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 10px;
}
.raw-patch pre {
  margin-left: 0;
  max-height: 220px;
}

.reasoning-state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--jade);
  font-size: 9px;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.story-layout {
  min-width: 0;
  min-height: 0;
  flex: 1;
  display: grid;
  grid-template-areas: 'copy';
  grid-template-columns: minmax(0, 1fr);

  &.with-portrait {
    grid-template-areas: 'copy portrait';
    grid-template-columns: minmax(0, 1fr) clamp(260px, 23vw, 360px);
  }
}

.story-scroll-shell {
  grid-area: copy;
  position: relative;
  min-width: 0;
  min-height: 0;
}

.story-scroll {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  padding: clamp(24px, 4vh, 46px) clamp(24px, 5vw, 72px) 48px;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}

.resume-stream-follow {
  position: absolute;
  right: 18px;
  bottom: 14px;
  z-index: 2;
  min-height: 32px;
  padding: 0 11px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--text-accent);
  background: color-mix(in srgb, var(--surface-raised) 94%, transparent);
  box-shadow: 0 10px 28px var(--stage-shadow);
  cursor: pointer;
}
.resume-stream-follow:hover {
  color: var(--gold);
  background: var(--button-hover);
}

.story-portrait {
  grid-area: portrait;
}

.story-copy {
  max-width: var(--reading-measure);
  margin: 0 auto;
  color: var(--text-primary);
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;
  font-size: var(--reading-font-size);
  line-height: var(--reading-line-height);
  text-align: justify;
  text-wrap: pretty;

  :deep(p) {
    margin: 0 0 1.2em;
  }
  text-shadow: 0 1px 1px color-mix(in srgb, var(--stage-shadow) 16%, transparent);

  :deep(q) {
    color: var(--text-accent);
    quotes: none;
  }
  :deep(q::before),
  :deep(q::after) {
    content: none;
  }
  :deep(blockquote) {
    margin: 20px 0;
    padding: 4px 0 4px 16px;
    border-left: 2px solid var(--gold);
    color: var(--text-accent);
    background: transparent;
  }
  :deep(em) {
    color: var(--gold-soft);
  }
}

.story-waiting,
.story-empty {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--text-secondary);
}

.story-interludes {
  width: min(100%, 820px);
  margin: 24px auto 8px;
  display: grid;
  gap: 7px;
}
.interlude-heading {
  padding: 0 3px 3px;
  color: var(--gold-soft);
  font-size: 9px;
  letter-spacing: 0.12em;
}
.story-interludes button {
  width: 100%;
  min-height: 48px;
  padding: 7px 11px;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  border: 1px solid color-mix(in srgb, var(--jade) 25%, var(--line-subtle));
  border-radius: 6px;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 5%, var(--surface-inset));
  text-align: left;
  cursor: pointer;
}
.story-interludes button:hover {
  border-color: var(--line-strong);
  color: var(--gold);
  background: var(--button-hover);
}
.story-interludes button span {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.story-interludes button small {
  color: var(--text-secondary);
  font-size: 8px;
}
.story-interludes button strong {
  overflow: hidden;
  color: var(--text-accent);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.story-waiting i {
  color: var(--gold);
}

.stream-status {
  min-height: 30px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-top: 1px solid var(--line-subtle);
  color: var(--jade);
  background: color-mix(in srgb, var(--surface-inset) 82%, transparent);
  font-size: 11px;
}

@media screen and (max-width: 760px) {
  .story-copy {
    font-size: max(var(--reading-font-size), 17px);
    text-align: left;
  }

  .story-scroll {
    padding: 22px 16px 42px;
    overscroll-behavior-y: contain;
    -webkit-overflow-scrolling: touch;
  }

  .turn-context-bar {
    min-height: 40px;
  }
  .reasoning-rail {
    padding: 0;
  }
  .turn-prompt-trigger,
  .reasoning-trigger,
  .variable-trigger {
    min-height: 40px;
    font-size: 12px;
  }
  .resume-stream-follow {
    right: 10px;
    bottom: 10px;
  }
  .turn-prompt-trigger {
    padding-inline: 10px;
    gap: 6px;
  }
  .turn-prompt-edit {
    min-width: 40px;
    padding: 0 10px;
  }
  .turn-prompt-edit span {
    display: none;
  }
  .reasoning-trigger {
    min-height: 44px;
    padding: 4px 9px 4px 4px;
    gap: 8px;
    border-radius: 7px;
  }
  .variable-trigger {
    padding-inline: 9px;
  }
  .variable-inline-detail {
    padding: 10px;
  }
  .variable-label {
    display: none;
  }
  .reasoning-trigger-glyph {
    width: 32px;
    height: 32px;
  }
  .reasoning-title {
    min-width: 90px;
  }
  .reasoning-title strong {
    font-size: 11px;
  }
  .reasoning-title small,
  .reasoning-ornament {
    display: none;
  }
  .context-popover {
    top: 42px;
    left: 8px;
    right: 8px;
    max-height: min(56vh, 420px);
  }
  .context-popover-copy {
    padding: 14px;
    font-size: 12px;
  }
  .variable-popover {
    max-height: min(66vh, 520px);
  }
  .variable-diagnostics {
    padding: 10px;
  }
  .analysis-segments {
    gap: 5px;
  }
  .analysis-segments span {
    padding: 3px 6px;
    font-size: 10px;
  }
  .operation-heading {
    align-items: flex-start;
  }
  .variable-operation pre,
  .operation-from,
  .operation-empty {
    margin-left: 0;
  }
}
