
.settings-scrim {
  position: fixed;
  inset: 0;
  z-index: 9000;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(2, 7, 10, 0.74);
  backdrop-filter: blur(8px);
}

.settings-panel {
  width: min(94vw, 720px);
  max-height: min(90dvh, 820px);
  overflow: auto;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--text-primary);
  background: var(--surface-raised);
  box-shadow: 0 28px 70px var(--stage-shadow);
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}

.settings-panel > header {
  position: sticky;
  top: 0;
  z-index: 2;
  min-height: 58px;
  padding: 0 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line-subtle);
  background: var(--header-bg);
  backdrop-filter: blur(12px);
}

.settings-panel > header > div {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--gold);
}
.settings-panel > header > div > span {
  display: grid;
  gap: 2px;
}
.settings-panel > header small {
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 400;
}
.settings-panel header button {
  width: 32px;
  height: 32px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}

.theme-setting,
.reading-settings {
  padding: 16px 18px;
  border-bottom: 1px solid var(--line-subtle);
}
.setting-heading {
  margin-bottom: 12px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}
.setting-heading > span {
  color: var(--text-accent);
  font-weight: 700;
}
.setting-heading small {
  color: var(--text-secondary);
  font-size: 10px;
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}
.theme-card {
  position: relative;
  min-width: 0;
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  align-items: center;
  gap: 11px;
  padding: 9px;
  overflow: hidden;
  border: 1px solid var(--line-subtle);
  border-radius: 7px;
  color: var(--text-primary);
  background: var(--surface-inset);
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}
.theme-card:hover {
  transform: translateY(-1px);
  border-color: var(--line-strong);
}
.theme-card.active {
  border-color: var(--preview-accent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--preview-accent) 25%, transparent),
    0 8px 24px var(--stage-shadow);
}
.theme-preview {
  position: relative;
  height: 66px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--preview-accent) 45%, transparent);
  border-radius: 5px;
  background: var(--preview-bg);
}
.theme-preview > i {
  position: absolute;
  top: 8px;
  left: 9px;
  z-index: 2;
  color: var(--preview-accent);
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--preview-accent) 45%, transparent));
}
.preview-window {
  position: absolute;
  inset: 20px 30px 8px 8px;
  border: 1px solid color-mix(in srgb, var(--preview-accent) 45%, transparent);
  background: var(--preview-surface);
}
.preview-rail {
  position: absolute;
  top: 20px;
  right: 8px;
  bottom: 8px;
  width: 17px;
  border: 1px solid color-mix(in srgb, var(--preview-accent) 38%, transparent);
  background: color-mix(in srgb, var(--preview-surface) 88%, transparent);
}
.theme-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}
.theme-copy strong {
  color: var(--text-accent);
}
.theme-copy small {
  display: -webkit-box;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 10px;
  line-height: 1.5;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}
.theme-check {
  position: absolute;
  top: 8px;
  right: 8px;
  color: var(--preview-accent);
  font-size: 10px;
}

.reading-settings {
  padding-bottom: 4px;
}
.range-setting,
.setting-group,
.reading-width-setting,
.dialogue-color-setting,
.toggle-setting {
  padding: 12px 0;
  border-bottom: 1px solid var(--line-subtle);
}
.range-setting {
  display: grid;
  gap: 9px;
}
.range-setting > span {
  display: flex;
  justify-content: space-between;
  color: var(--text-accent);
}
.range-setting output {
  color: var(--gold);
  font-variant-numeric: tabular-nums;
}
.range-setting input {
  width: 100%;
  accent-color: var(--gold);
}
.dialogue-color-setting {
  display: grid;
  gap: 10px;
}
.dialogue-color-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.dialogue-color-heading > span {
  display: grid;
  gap: 2px;
  color: var(--text-accent);
}
.dialogue-color-heading > span small {
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 400;
}
.dialogue-color-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}
.dialogue-color-controls input[type='color'] {
  width: 38px;
  height: 30px;
  padding: 2px;
  border: 1px solid var(--line-strong);
  border-radius: 5px;
  background: var(--surface-inset);
  cursor: pointer;
}
.dialogue-color-controls output {
  min-width: 66px;
  color: var(--text-secondary);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}
.dialogue-color-controls button {
  min-height: 30px;
  padding: 0 9px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--gold-soft);
  background: var(--surface-inset);
  cursor: pointer;
}
.dialogue-color-controls button:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}
.dialogue-color-palette {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
}
.dialogue-color-palette > button {
  min-width: 0;
  padding: 5px;
  display: grid;
  gap: 4px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}
.dialogue-color-palette > button:hover,
.dialogue-color-palette > button.active {
  border-color: var(--gold);
  color: var(--text-accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--gold) 18%, transparent);
}
.palette-swatch {
  width: 100%;
  height: 22px;
  border: 1px solid color-mix(in srgb, var(--text-primary) 28%, transparent);
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #fff 18%, transparent);
}
.palette-label {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  font-size: 10px;
  white-space: nowrap;
}
.palette-label small {
  padding: 1px 3px;
  border-radius: 3px;
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 12%, transparent);
  font-size: 8px;
}
.reading-width-setting {
  display: grid;
  gap: 10px;
}
.reading-width-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.reading-width-heading > span {
  display: grid;
  gap: 2px;
}
.reading-width-heading small {
  color: var(--text-secondary);
  font-size: 10px;
}
.reading-width-heading output {
  min-width: 46px;
  color: var(--gold);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.reading-width-setting > input {
  width: 100%;
  accent-color: var(--gold);
}
.width-preset-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.width-preset-row button {
  min-height: 34px;
  padding: 5px 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}
.width-preset-row button small {
  color: color-mix(in srgb, var(--text-secondary) 76%, transparent);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-size: 9px;
}
.width-preset-row button.active {
  border-color: color-mix(in srgb, var(--gold) 48%, var(--line-subtle));
  color: var(--gold);
  background: var(--button-active);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--gold) 8%, transparent);
}
.width-preset-row button.active small {
  color: var(--gold-soft);
}
.setting-group {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--text-accent);
}
.segmented-control {
  display: flex;
  padding: 2px;
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
  background: var(--surface-inset);
}
.segmented-control button {
  min-width: 48px;
  padding: 6px 10px;
  border: 0;
  border-radius: 4px;
  color: var(--text-secondary);
  background: transparent;
  cursor: pointer;
}
.segmented-control button.active {
  color: var(--gold);
  background: var(--button-active);
}
.reasoning-appearance-setting > span {
  display: grid;
  gap: 2px;
}
.reasoning-appearance-setting > span small {
  color: var(--text-secondary);
  font-size: 10px;
}
.reasoning-appearance-setting .segmented-control button {
  min-width: 66px;
}
.toggle-setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  cursor: pointer;
}
.toggle-setting > span {
  display: grid;
  gap: 2px;
}
.toggle-setting small {
  color: var(--text-secondary);
}
.toggle-setting input {
  width: 18px;
  height: 18px;
  accent-color: var(--jade);
}
.settings-panel footer {
  padding: 12px 18px;
  display: flex;
  justify-content: flex-end;
}
.settings-panel footer button {
  padding: 7px 10px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}
.settings-fade-enter-active,
.settings-fade-leave-active {
  transition: opacity 0.18s ease;
}
.settings-fade-enter-from,
.settings-fade-leave-to {
  opacity: 0;
}

@media screen and (max-width: 620px) {
  .settings-scrim {
    padding: 8px;
  }
  .settings-panel {
    width: calc(100vw - 16px);
    max-height: calc(100dvh - 16px);
  }
  .theme-setting,
  .reading-settings {
    padding: 14px 12px;
  }
  .theme-grid {
    grid-template-columns: 1fr;
  }
  .theme-card {
    grid-template-columns: 82px minmax(0, 1fr);
  }
  .dialogue-color-heading {
    align-items: flex-start;
    flex-direction: column;
  }
  .dialogue-color-palette {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .reasoning-appearance-setting {
    align-items: stretch;
    flex-direction: column;
  }
  .reasoning-appearance-setting .segmented-control {
    width: 100%;
  }
  .reasoning-appearance-setting .segmented-control button {
    min-width: 0;
    flex: 1;
    padding-inline: 6px;
  }
}
