
.variable-diagnostics {
  min-height: 0;
  overflow-y: auto;
  padding: 14px;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}

.variable-analysis {
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line-subtle);
  border-left: 2px solid var(--gold);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
}

.variable-analysis h3 {
  margin: 0 0 9px;
  color: var(--gold-soft);
  font-size: 11px;
  font-weight: 600;
}

.analysis-segments {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.analysis-segments span {
  padding: 4px 8px;
  border: 1px solid var(--line-subtle);
  border-radius: 999px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 70%, transparent);
  font-size: 11px;
  line-height: 1.45;
}

.variable-overview {
  min-height: 32px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-secondary);
  font-size: 11px;
}

.variable-overview > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-accent);
}

.variable-overview > span:first-child i {
  color: var(--jade);
}

.variable-overview strong {
  color: var(--gold-soft);
  font-weight: 600;
}

.diagnostic-state {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.diagnostic-state.valid {
  color: var(--semantic-success);
}

.diagnostic-state.receiving {
  color: var(--jade);
}

.diagnostic-state.invalid {
  color: var(--semantic-danger);
}

.variable-operation-list {
  margin: 0;
  padding: 0;
  display: grid;
  gap: 7px;
  list-style: none;
}

.variable-operation {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--line-subtle);
  background: color-mix(in srgb, var(--surface-inset) 58%, transparent);
}

.operation-heading {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.operation-index {
  width: 20px;
  height: 20px;
  flex: none;
  display: inline-grid;
  place-items: center;
  border: 1px solid var(--line-subtle);
  border-radius: 50%;
  color: var(--text-secondary);
  font-size: 9px;
}

.operation-kind {
  min-width: 34px;
  flex: none;
  color: var(--gold-soft);
  font-size: 10px;
  text-align: center;
}

.operation-kind.op-delta {
  color: var(--jade);
}

.operation-kind.op-remove {
  color: var(--semantic-danger);
}

.operation-kind.op-insert,
.operation-kind.op-add {
  color: var(--semantic-success);
}

.operation-heading code {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--text-primary);
  font-family: 'Microsoft YaHei UI', system-ui, sans-serif;
  font-size: 11px;
}

.variable-operation pre,
.raw-patch pre {
  margin: 8px 0 0 28px;
  padding: 8px 10px;
  overflow-x: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  border-left: 1px solid var(--line-strong);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-raised) 72%, transparent);
  font:
    11px/1.6 ui-monospace,
    SFMono-Regular,
    Consolas,
    monospace;
}

.operation-from,
.operation-empty {
  margin: 7px 0 0 28px;
  color: var(--text-secondary);
  font-size: 10px;
}

.variable-empty {
  padding: 22px;
  color: var(--text-secondary);
  text-align: center;
  font-size: 11px;
}

.diagnostic-error {
  margin-top: 10px;
  padding: 9px 11px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 55%, var(--line-subtle));
  color: var(--semantic-danger);
  background: color-mix(in srgb, var(--semantic-danger) 8%, transparent);
  font-size: 11px;
}

.raw-patch {
  margin-top: 10px;
  border-top: 1px solid var(--line-subtle);
}

.raw-patch summary {
  padding: 10px 2px 0;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 10px;
}

.raw-patch pre {
  margin-left: 0;
  max-height: 220px;
}

.variable-diagnostics.dense {
  padding: 12px;
}

@media (max-width: 640px) {
  .variable-diagnostics {
    padding: 11px;
  }

  .analysis-segments {
    display: grid;
  }

  .analysis-segments span {
    border-radius: 4px;
  }

  .operation-heading {
    flex-wrap: wrap;
  }

  .variable-operation pre,
  .operation-from,
  .operation-empty {
    margin-left: 0;
  }
}
