
.inventory-panel {
  display: flex;
  flex-direction: column;
  gap: 22px;
  color: var(--text-primary);
}

.inventory-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.section-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-accent);

  i {
    color: var(--gold);
  }
}

.spirit-stone-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 10px;
  border: 1px solid color-mix(in srgb, var(--gold) 28%, transparent);
  border-radius: 999px;
  color: var(--gold);
  font-size: 12px;
  font-variant-numeric: tabular-nums;

  i {
    font-size: 11px;
  }
}

.items-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.item-strip {
  --tier-color: var(--text-secondary);

  padding: 11px 14px;
  border: 1px solid color-mix(in srgb, var(--line-subtle) 55%, transparent);
  border-left: 2px solid color-mix(in srgb, var(--tier-color) 48%, transparent);
  border-radius: 5px;
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--tier-color) 4%, transparent), transparent 44%),
    linear-gradient(90deg, color-mix(in srgb, var(--surface-inset) 24%, transparent), transparent);
  &:focus {
    outline: 1px solid var(--gold);
    outline-offset: 3px;
  }

  &.tier-heaven {
    --tier-color: var(--gold);
  }
  &.tier-earth {
    --tier-color: var(--jade);
  }
  &.tier-mystic {
    --tier-color: var(--semantic-info);
  }
  &.tier-yellow {
    --tier-color: var(--semantic-warning);
  }
  &.tier-mortal {
    --tier-color: var(--text-secondary);
  }
}

.item-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.item-title-group {
  min-width: 0;
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

.item-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.item-rank {
  padding: 0 5px;
  border-radius: 3px;
  font-size: 11px;
  color: var(--tier-color);
  background: color-mix(in srgb, var(--tier-color) 8%, transparent);
}

.item-count {
  flex: none;
  font-size: 12px;
  color: var(--gold-soft);
  font-variant-numeric: tabular-nums;
}

.item-desc {
  margin-top: 5px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-secondary);
}

.empty-hint {
  padding: 16px 0;
  text-align: center;
  font-size: 12px;
  font-style: italic;
  color: var(--text-secondary);
  opacity: 0.65;
}

@media screen and (max-width: 480px) {
  .inventory-panel {
    gap: 18px;
  }

  .item-strip {
    padding: 9px 12px;
  }

  .item-name {
    font-size: 13px;
  }

  .item-desc {
    font-size: 11.5px;
  }
}
