
.companions-panel {
  --companion-muted: color-mix(in srgb, var(--text-secondary) 50%, var(--text-primary));
  --romance: var(--semantic-relation);
  --romance-faint: color-mix(in srgb, var(--romance) 6%, transparent);
  --romance-line: color-mix(in srgb, var(--romance) 30%, var(--line-subtle));
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 18px;
  color: var(--text-primary);
}
button {
  font: inherit;
  cursor: pointer;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
button:focus-visible,
.scroll-page:focus-visible,
.portrait-button:focus-within {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
.companions-topbar {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 16px;
  flex: none;
}
.roster-strip {
  min-width: 0;
  flex: 1;
  display: flex;
  gap: 8px;
  padding: 3px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--romance-line) transparent;
}
.roster-chip {
  height: 40px;
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 10px 5px 5px;
  border: 1px solid transparent;
  border-radius: 5px;
  color: var(--companion-muted);
  background: transparent;
  transition:
    color 0.18s,
    border-color 0.18s;
}
.roster-chip:hover {
  color: var(--text-primary);
  background: var(--romance-faint);
}
.roster-chip.active {
  color: var(--text-primary);
  border-color: var(--romance-line);
  border-bottom-color: var(--romance);
}
.roster-portrait {
  width: 28px;
  height: 28px;
  flex: none;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 50%;
  color: var(--romance);
  background: var(--romance-faint);
  font-family: 'Songti SC', 'STSong', serif;
}
.roster-portrait img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
}
.roster-name {
  font-size: 13px;
  white-space: nowrap;
}
.roster-favor {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--romance);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.roster-favor.neutral {
  color: var(--companion-muted);
}
.roster-favor i {
  font-size: 9px;
}
.ledger-title {
  flex: 1;
  color: var(--text-accent);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 15px;
}
.ledger-switch {
  flex: none;
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--line-strong);
}
.ledger-switch button {
  padding: 7px 4px;
  border: 0;
  background: transparent;
  color: var(--companion-muted);
  font-size: 12px;
  white-space: nowrap;
}
.ledger-switch button.active {
  color: var(--romance);
}
.ledger-switch button span {
  margin-left: 3px;
  font-variant-numeric: tabular-nums;
}
.ledger-divider {
  font-size: 11px;
}

.companion-scroll {
  min-width: 0;
  min-height: 0;
  flex: 1;
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr);
  gap: 28px;
}
.scroll-left-column {
  position: relative;
  min-width: 0;
  min-height: 0;
  padding-right: 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.scroll-left-column::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 1px;
  background: linear-gradient(180deg, transparent, var(--line-subtle) 15% 85%, transparent);
}
.portrait-seat {
  min-height: 0;
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: center;
}
.portrait-frame {
  position: relative;
  height: 100%;
  max-height: 330px;
  max-width: 220px;
  aspect-ratio: 2 / 3;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--gold) 35%, var(--line-subtle));
  border-radius: 3px;
  color: var(--romance);
  background: var(--romance-faint);
}
.portrait-frame::after {
  content: '';
  position: absolute;
  inset: 5px;
  border: 1px solid color-mix(in srgb, var(--gold) 42%, transparent);
  pointer-events: none;
  mask:
    linear-gradient(90deg, #000 12px, transparent 12px calc(100% - 12px), #000 calc(100% - 12px)),
    linear-gradient(#000 12px, transparent 12px calc(100% - 12px), #000 calc(100% - 12px));
  mask-composite: intersect;
}
.portrait-frame > img {
  width: 100%;
  height: 100%;
  position: absolute;
  inset: 0;
  object-fit: cover;
  border-radius: inherit;
}
.portrait-monogram {
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 48px;
}
.relation-badge {
  position: absolute;
  bottom: 10px;
  left: 9px;
  max-width: calc(100% - 18px);
  box-sizing: border-box;
  padding: 5px 8px;
  border-left: 2px solid var(--gold);
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface) 86%, transparent);
  backdrop-filter: blur(8px);
  font-size: 10px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.portrait-edit {
  position: absolute;
  top: 9px;
  right: 9px;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--romance-line);
  border-radius: 50%;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface) 82%, transparent);
  backdrop-filter: blur(8px);
  font-size: 12px;
}
.identity-block {
  flex: none;
  min-width: 0;
}
.identity-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px 10px;
}
.identity-heading h2 {
  margin: 0;
  color: var(--text-primary);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 24px;
  font-weight: 650;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.identity-heading > span {
  font-size: 12px;
}
.realm-text {
  color: var(--realm-color);
}
.light-theme .realm-text {
  color: color-mix(in srgb, var(--realm-color) 20%, var(--text-primary));
}
.current-mood {
  margin: 8px 0 12px;
  color: var(--companion-muted);
  font-size: 12px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.affinity-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: var(--companion-muted);
}
.affinity-heading strong {
  color: var(--romance);
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.affinity-heading small {
  font-size: 11px;
  font-weight: 400;
}
.affinity-track {
  height: 4px;
  margin-top: 7px;
  overflow: hidden;
  border-radius: 2px;
  background: var(--progress-bg);
}
.affinity-track > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--romance) 60%, var(--gold)), var(--romance));
  transition: width 0.3s ease;
}
.talk-actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
.talk-btn {
  min-width: 0;
  flex: 1;
  min-height: 36px;
  padding: 7px 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  border: 1px solid var(--romance-line);
  border-radius: 6px;
  color: var(--text-primary);
  background: var(--romance-faint);
  font-size: 12px;
  line-height: 1.5;
  text-align: left;
  transition:
    border-color 0.18s,
    background 0.18s;
}
.talk-btn:hover:enabled {
  border-color: var(--romance);
  background: color-mix(in srgb, var(--romance) 12%, transparent);
}
.talk-btn i {
  color: var(--romance);
  font-size: 10px;
}

.scroll-right-column {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.scroll-tabs {
  display: flex;
  flex: none;
  align-items: center;
  gap: 28px;
  border-bottom: 1px solid var(--line-subtle);
}
.scroll-tabs button {
  position: relative;
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 9px 2px 13px;
  border: 0;
  color: var(--companion-muted);
  background: transparent;
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 15px;
}
.scroll-tabs button.active {
  color: var(--text-primary);
}
.scroll-tabs button.active::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--romance), var(--gold));
}
.scroll-tabs small {
  font-family: sans-serif;
  font-size: 10px;
  color: var(--romance);
}
.scroll-page {
  min-width: 0;
  min-height: 0;
  flex: 1;
  padding: 20px 6px 4px 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--line-subtle) transparent;
  overflow-wrap: anywhere;
  color: var(--companion-muted);
  font-size: 12px;
  line-height: 1.65;
}
.scroll-page p {
  white-space: pre-line;
}
.scroll-page h3 {
  margin: 0;
  font-size: 11px;
  font-weight: 500;
}
.impression-block {
  margin-bottom: 20px;
}
.impression-block p {
  margin: 9px 0 0;
  color: var(--text-primary);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 14.5px;
  line-height: 1.9;
}
.notes-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.relationship-note {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  align-items: baseline;
  gap: 8px;
  padding-left: 12px;
  border-left: 2px solid var(--romance);
}
.relationship-note p,
.relationship-promise p {
  margin: 0;
  font-size: 13px;
  line-height: 1.75;
}
.relationship-note p {
  color: var(--text-primary);
}
.taboo-note {
  border-color: var(--semantic-warning);
}
.relationship-promise {
  margin-top: 22px;
  padding: 3px 0 3px 12px;
  border-left: 2px solid color-mix(in srgb, var(--gold) 60%, transparent);
}
.relationship-promise h3 {
  color: var(--gold);
}
.relationship-promise p {
  margin: 7px 0 0;
}
.cultivation-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.cultivation-heading strong {
  color: var(--jade);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.cultivation-track {
  height: 5px;
  margin-top: 9px;
  overflow: hidden;
  border-radius: 3px;
  background: var(--progress-bg);
}
.cultivation-track > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--jade), var(--gold));
}
.cultivation-progress > p {
  margin: 8px 0 0;
}
.cultivation-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px 24px;
  margin: 24px 0;
}
.cultivation-stat {
  min-width: 0;
}
.cultivation-stat dt {
  margin-bottom: 7px;
  font-size: 11px;
}
.cultivation-stat dd {
  margin: 0;
}
.cultivation-stat strong {
  color: var(--text-primary);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 14px;
  font-weight: 600;
}
.cultivation-stat p {
  margin: 7px 0 0;
}
.skill-record {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  align-items: baseline;
  gap: 8px;
}
.skill-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.skill-tags span {
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--jade) 26%, var(--line-subtle));
  border-radius: 3px;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 5%, transparent);
  font-size: 11px;
  line-height: 1.5;
}
.skill-record p {
  margin: 0;
}
.chronicle-timeline {
  padding: 0 0 0 10px;
}
.chronicle-entry {
  position: relative;
  padding: 0 0 22px 24px;
  border-left: 1px solid var(--line-subtle);
}
.chronicle-entry:last-child {
  padding-bottom: 4px;
}
.chronicle-mark {
  position: absolute;
  top: 0;
  left: -10px;
  width: 19px;
  height: 23px;
  display: grid;
  place-items: center;
  background: var(--surface);
  font-size: 10px;
}
.chronicle-entry.latest .chronicle-mark {
  color: var(--romance);
}
.chronicle-copy header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px 14px;
}
.chronicle-copy h3 {
  color: var(--text-primary);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 14px;
  font-weight: 600;
}
.chronicle-copy time {
  font-size: 11px;
  line-height: 1.6;
}
.chronicle-type {
  display: inline-block;
  margin-top: 5px;
  color: var(--romance);
  font-size: 10px;
}
.chronicle-copy p {
  margin: 6px 0 0;
  font-size: 12.5px;
  line-height: 1.75;
}

.npc-ledger {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  scrollbar-width: thin;
}
.npc-ledger-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 32px;
}
.npc-entry {
  min-width: 0;
  padding: 14px 0;
  border-bottom: 1px solid var(--line-subtle);
}
.npc-entry header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}
.npc-entry h3 {
  margin: 0;
  color: var(--text-primary);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 16px;
  overflow-wrap: anywhere;
}
.npc-entry header > span {
  font-size: 12px;
}
.npc-affiliation {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 8px;
  color: var(--gold);
  font-size: 11px;
}
.npc-entry p {
  margin: 8px 0 0;
  color: var(--companion-muted);
  font-size: 13px;
  line-height: 1.75;
  overflow-wrap: anywhere;
  white-space: pre-line;
}
.volume-empty,
.companions-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 36px 16px;
  color: var(--companion-muted);
  text-align: center;
}
.companions-empty {
  flex: 1;
}
.volume-empty strong,
.companions-empty strong {
  color: var(--text-accent);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 16px;
  font-weight: 500;
}
.volume-empty p,
.companions-empty p {
  margin: 0;
  font-size: 12px;
  line-height: 1.75;
}

.portrait-dialog {
  box-sizing: border-box;
  width: min(460px, calc(100% - 32px));
  max-height: calc(100% - 32px);
  padding: 22px;
  border: 1px solid var(--romance-line);
  border-radius: 8px;
  color: var(--text-primary);
  background: var(--surface);
  box-shadow: 0 16px 48px color-mix(in srgb, var(--stage-shadow) 45%, transparent);
}
.portrait-dialog::backdrop {
  background: rgb(0 0 0 / 38%);
  backdrop-filter: blur(3px);
}
.portrait-dialog-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.portrait-dialog-heading h3 {
  margin: 0;
  color: var(--text-primary);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 16px;
}
.portrait-dialog-close {
  width: 28px;
  height: 28px;
  flex: none;
  padding: 0;
  border: 0;
  border-radius: 4px;
  color: var(--companion-muted);
  background: transparent;
}
.portrait-dialog-close:hover {
  color: var(--romance);
  background: var(--romance-faint);
}
.portrait-hint {
  margin: 12px 0 18px;
  color: var(--companion-muted);
  font-size: 12px;
  line-height: 1.65;
}
.portrait-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}
.portrait-slot {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.portrait-preview {
  width: 100%;
  aspect-ratio: 2 / 3;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--line-subtle);
  border-radius: 4px;
  color: var(--companion-muted);
  background: var(--romance-faint);
  font-size: 11px;
}
.portrait-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.portrait-slot > strong {
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
}
.portrait-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.portrait-button {
  position: relative;
  box-sizing: border-box;
  min-height: 32px;
  padding: 6px 9px;
  border: 1px solid var(--romance-line);
  border-radius: 4px;
  color: var(--text-primary);
  background: var(--romance-faint);
  font-size: 11px;
  line-height: 1.5;
  cursor: pointer;
}
.portrait-button.ghost {
  color: var(--companion-muted);
  background: transparent;
}
.portrait-button.uploading {
  opacity: 0.55;
  cursor: wait;
}
.portrait-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: inherit;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.reduce-motion .companions-panel *,
.reduce-motion .companions-panel *::after {
  transition: none !important;
  scroll-behavior: auto;
}

@media screen and (max-width: 760px) {
  .companions-panel {
    height: auto;
    gap: 14px;
  }
  .companions-topbar {
    gap: 6px;
  }
  .roster-strip {
    gap: 5px;
  }
  .roster-chip {
    gap: 6px;
    padding-right: 7px;
  }
  .ledger-switch {
    gap: 2px;
  }
  .ledger-switch button {
    padding: 7px 2px;
    font-size: 11px;
  }
  .companion-scroll {
    flex: none;
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }
  .scroll-left-column {
    display: grid;
    grid-template-columns: 96px minmax(0, 1fr);
    align-items: start;
    gap: 14px;
    padding: 0;
  }
  .scroll-left-column::after {
    display: none;
  }
  .portrait-seat {
    display: block;
  }
  .portrait-frame {
    width: 96px;
    height: auto;
    max-height: none;
  }
  .relation-badge {
    bottom: 6px;
    left: 5px;
    max-width: calc(100% - 10px);
    padding: 4px;
    font-size: 9px;
  }
  .portrait-edit {
    top: 5px;
    right: 5px;
  }
  .identity-heading h2 {
    font-size: 21px;
  }
  .identity-heading > span {
    font-size: 11px;
  }
  .current-mood {
    margin: 6px 0 10px;
  }
  .talk-actions {
    margin-top: 10px;
  }
  .talk-btn {
    padding: 6px 8px;
    font-size: 11px;
  }
  .scroll-tabs {
    gap: 30px;
  }
  .scroll-page {
    flex: none;
    overflow: visible;
    padding: 16px 0 4px;
  }
  .cultivation-grid {
    gap: 18px;
  }
  .npc-ledger {
    overflow: visible;
  }
  .npc-ledger-list {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media screen and (max-width: 480px) {
  .cultivation-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .relationship-note {
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 6px;
    padding-left: 9px;
  }
  .portrait-dialog {
    padding: 16px;
  }
  .portrait-grid {
    gap: 12px;
  }
}
