
.affairs-panel {
  padding: 20px;
  color: var(--text-primary);
}
.location-brief {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 24px 0;
  padding: 20px 0;
  border-top: 1px solid var(--line-subtle);
  border-bottom: 1px solid var(--line-subtle);
}
.brief-header {
  text-align: center;
}
.brief-label {
  font-size: 12px;
  color: var(--text-secondary);
  letter-spacing: 2px;
  margin-bottom: 8px;
}
.brief-title {
  font-size: 26px;
  font-weight: bold;
  color: var(--text-accent);
  margin-bottom: 6px;
  font-family: 'Songti SC', STSong, serif;
}
.brief-domain {
  font-size: 14px;
  color: var(--gold);
}
.brief-desc {
  text-align: center;
  padding: 16px 24px;
  line-height: 1.8;
  color: var(--text-secondary);
  font-size: 14px;
  background: var(--surface-inset);
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
}
.brief-desc i {
  color: var(--gold);
  opacity: 0.4;
  font-size: 12px;
  margin: 0 12px;
  vertical-align: super;
}
.brief-routes {
  margin-top: 8px;
}
.routes-title,
.connections-list {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}
.routes-title {
  margin-bottom: 12px;
  font-size: 13px;
  color: var(--text-secondary);
}
.routes-title i {
  color: var(--gold);
}
.connections-list {
  flex-wrap: wrap;
}
.connections-list button {
  padding: 6px 16px;
  background: var(--bg-primary);
  border: 1px solid var(--line-subtle);
  border-radius: 20px;
  font-size: 13px;
  color: var(--text-primary);
  cursor: pointer;
}
.connections-list i {
  margin-right: 8px;
  color: var(--gold);
  font-size: 11px;
}
.ledger-section {
  margin-bottom: 20px;
}
h2 {
  font-size: 18px;
  margin: 0 0 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line-subtle);
  display: flex;
  gap: 10px;
  align-items: center;
  font-family: 'Songti SC', STSong, serif;
}
h2 i {
  color: var(--gold);
  font-size: 16px;
}
h2 > span {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 400;
  margin-left: auto;
}
.ledger-card {
  padding: 9px 2px 10px;
  margin-bottom: 5px;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--line-subtle);
  border-radius: 0;
  overflow-wrap: anywhere;
}
.ledger-card.tracked h3 {
  color: var(--gold);
}
.ledger-card:focus {
  outline: 1px solid var(--gold);
  outline-offset: 3px;
}
.ledger-card header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-bottom: 5px;
}
h3 {
  font-size: 15px;
  font-weight: 600;
  margin: 0;
  flex: 1;
}
.type-label {
  font-size: 11px;
  color: var(--gold);
  padding: 2px 6px;
  white-space: nowrap;
}
.ledger-card p {
  margin: 4px 0;
  font-size: 13px;
  line-height: 1.65;
  color: var(--text-secondary);
}
.task-progress > span,
.task-next > span,
.event-change > span {
  color: var(--gold);
  margin-right: 12px;
  font-size: 12px;
}
.ledger-card .task-next {
  color: var(--text-primary);
}
.track-button {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 0;
  padding: 4px 0 4px 8px;
  color: var(--text-secondary);
  background: transparent;
  font-size: 11px;
  cursor: pointer;
}
.track-button[aria-pressed='true'] {
  color: var(--gold);
}
footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 5px;
}
footer :deep(.affairs-links) {
  margin-top: 0;
}
footer > button,
.result-link {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--gold);
  font-size: 12px;
  text-align: left;
  cursor: pointer;
}
.intent-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--gold) 30%, transparent);
  border-radius: 0;
  padding: 4px 0;
  background: transparent;
  color: var(--gold);
  font-size: 12px;
  cursor: pointer;
}
footer > .intent-button {
  margin-left: auto;
}
.event-card h3 {
  color: var(--jade);
}
.event-card.settled h3 {
  color: var(--text-secondary);
}
.event-status,
.event-origin,
small {
  font-size: 12px;
  color: var(--text-secondary);
}
.effects {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.effects span {
  font-size: 11px;
  color: var(--jade);
}
.result-card h3 {
  color: var(--text-primary);
}
.result-card .result-link {
  display: block;
  margin-top: 10px;
}
.empty-hint,
.calm-state {
  font-size: 13px;
  line-height: 1.9;
  color: var(--text-secondary);
  padding: 12px 0;
}
.reputation-section {
  color: var(--text-secondary);
  font-size: 13px;
  padding-top: 16px;
  border-top: 1px solid var(--line-subtle);
}
summary {
  cursor: pointer;
}
.reputation-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 0;
}
button:disabled {
  opacity: 0.5;
  cursor: default;
}
@media (max-width: 600px) {
  .affairs-panel {
    padding: 12px;
  }
  .location-brief {
    margin-top: 16px;
  }
  .brief-desc {
    padding: 14px;
  }
  .ledger-card {
    padding: 9px 0;
  }
  .ledger-card header {
    gap: 8px;
  }
  .track-button {
    padding-left: 0;
  }
}
