
.skills-panel {
  color: var(--text-primary);
}

.skills-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.skill-strip {
  --rank-color: var(--gold);

  position: relative;
  overflow: hidden;
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--line-subtle) 55%, transparent);
  border-left: 2px solid color-mix(in srgb, var(--rank-color) 48%, transparent);
  border-radius: 5px;
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--rank-color) 4%, transparent), transparent 44%),
    linear-gradient(90deg, color-mix(in srgb, var(--surface-inset) 24%, transparent), transparent);

  &::before {
    content: '';
    position: absolute;
    top: 17px;
    right: 0;
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: var(--rank-color);
  }

  &.rank-tier-heaven {
    --rank-color: var(--gold);
  }
  &.rank-tier-earth {
    --rank-color: var(--jade);
  }
  &.rank-tier-mystic {
    --rank-color: var(--semantic-info);
  }
  &.rank-tier-yellow {
    --rank-color: var(--semantic-warning);
  }
  &.rank-tier-mortal {
    --rank-color: var(--text-secondary);
  }
}

.skill-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.skill-title-group {
  min-width: 0;
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px;
}

.skill-name {
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 15px;
  font-weight: 700;
  color: var(--gold);
}

.skill-type {
  font-size: 11px;
  color: var(--text-secondary);
}

.skill-rank {
  flex: none;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  color: var(--rank-color);
  background: color-mix(in srgb, var(--rank-color) 12%, transparent);
}

.skill-desc {
  margin: 7px 0 9px;
  font-size: 12.5px;
  line-height: 1.65;
  color: var(--text-secondary);
}

.skill-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.skill-proficiency {
  font-size: 11px;
  color: var(--text-accent);
}

.proficiency-pips {
  display: inline-flex;
  align-items: center;
  gap: 4px;

  .pip {
    width: 8px;
    height: 3px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--line-subtle) 85%, transparent);

    &.filled {
      background: var(--rank-color);
    }
  }
}

.empty-hint {
  padding: 20px 0;
  text-align: center;
  font-size: 12px;
  font-style: italic;
  color: var(--text-secondary);
}

@media screen and (max-width: 480px) {
  .skills-list {
    gap: 10px;
  }

  .skill-strip {
    padding: 10px 12px;
  }

  .skill-name {
    font-size: 14px;
  }

  .skill-desc {
    font-size: 12px;
  }
}
