
.inline-input-editor {
  width: 100%;
  min-width: 0;
  padding: 7px;
  display: grid;
  gap: 7px;
  border: 1px solid color-mix(in srgb, var(--gold) 42%, var(--line-strong));
  border-radius: 6px;
  background: color-mix(in srgb, var(--surface-inset) 92%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--gold) 6%, transparent),
    0 0 18px color-mix(in srgb, var(--accent-glow) 12%, transparent);
}

textarea {
  width: 100%;
  min-height: 86px;
  max-height: 240px;
  padding: 10px 11px;
  resize: vertical;
  overflow-y: auto;
  border: 1px solid var(--line-subtle);
  border-radius: 4px;
  color: var(--text-primary);
  caret-color: var(--gold);
  background: color-mix(in srgb, var(--reading-surface) 86%, var(--surface-inset));
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;
  font-size: max(12px, calc(var(--reading-font-size) * 0.82));
  line-height: 1.7;
  overflow-wrap: anywhere;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}

textarea:focus {
  border-color: color-mix(in srgb, var(--gold) 62%, var(--line-strong));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--gold) 15%, transparent);
}

.inline-edit-error {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--semantic-danger);
  font-size: 10px;
}

footer {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

footer > span {
  color: var(--text-secondary);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

footer > span.invalid {
  color: var(--semantic-danger);
}

footer > div {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 6px;
}

button {
  min-height: 29px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line-subtle);
  border-radius: 4px;
  color: var(--text-secondary);
  background: var(--button-bg);
  font-size: 10px;
  cursor: pointer;
}

button:hover:not(:disabled) {
  border-color: var(--line-strong);
  color: var(--text-primary);
  background: var(--button-hover);
}

button.save-button {
  border-color: color-mix(in srgb, var(--gold) 38%, var(--line-subtle));
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 9%, var(--button-active));
}

button:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.inline-input-editor.dialogue textarea {
  font-size: var(--reading-font-size);
}

.inline-input-editor.bar {
  margin: 10px 14px 0;
  width: calc(100% - 28px);
}

@media screen and (max-width: 760px) {
  .inline-input-editor {
    padding: 6px;
  }

  .inline-input-editor.bar {
    margin: 8px 9px 0;
    width: calc(100% - 18px);
  }

  textarea {
    min-height: 96px;
    padding: 9px;
    font-size: max(13px, calc(var(--reading-font-size) * 0.82));
  }
}
