
.world-atlas {
  .focus-preview { display: grid; gap: 4px; padding: 6px 10px; border-left: 1px solid var(--gold); font-size: 11px; color: var(--text-secondary); }
  .focus-preview strong { color: var(--gold); font-size: 13px; }
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #0c2028;
}
.traveler-bar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 9px 16px;
  border-bottom: 1px solid #b5a57c33;
  background: linear-gradient(100deg, #163532, #0b2029);
  color: #b9c7b7;
}
button {
  font: inherit;
  cursor: pointer;
}
button:focus-visible {
  outline: 2px solid #d4b577;
  outline-offset: 2px;
}
.locate-button {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  color: #dac99f;
  border: 0;
  padding: 0;
  background: transparent;
  text-align: left;
}
.locate-button:disabled {
  cursor: default;
}
.locate-button > i {
  font-size: 19px;
  color: #a2c6ab;
}
.location-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.location-text small {
  color: #8fa798;
  font-size: 9px;
  letter-spacing: 1px;
}
.location-text strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 350px;
  font:
    17px 'KaiTi',
    serif;
}
.location-domain {
  color: #96ada1;
  padding-left: 12px;
  border-left: 1px solid #b5a57c33;
  font-size: 11px;
  white-space: nowrap;
}
.location-accuracy {
  color: #718e88;
  font-size: 10px;
  margin-left: auto;
  white-space: nowrap;
}
.current-danger {
  border: 1px solid #b5a57c44;
  border-radius: 3px;
  padding: 3px 8px;
  color: #d0bf98;
  white-space: nowrap;
  font-size: 11px;
}
.connections-button {
  display: flex;
  gap: 8px;
  align-items: center;
  white-space: nowrap;
  padding: 6px 0 6px 10px;
  color: #98aaa0;
  border: 0;
  background: transparent;
  font-size: 11px;
}
.connections-button b {
  font-weight: normal;
  color: #d2bd8f;
}
.connections {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 7px;
  padding: 9px 16px;
  max-height: 90px;
  overflow-y: auto;
  border-bottom: 1px solid #b5a57c33;
}
.connections span {
  color: #b7c6b5;
  font-size: 11px;
  border: 1px solid #b5a57c30;
  border-radius: 3px;
  padding: 4px 9px;
}
.connections .empty-connections {
  border: 0;
  color: #7f9991;
}
.atlas-frame {
  flex: 1;
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 0;
}
.atlas-host {
  flex: 1;
  min-width: 0;
  min-height: 0;
}
.atlas-message {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: 15px;
  align-items: center;
  justify-content: center;
  background: #0c2028;
  color: #a8b6a5;
  font-size: 12px;
}
.atlas-message > i {
  font-size: 26px;
  color: #c5b486;
}
.atlas-message button {
  padding: 7px 16px;
  border: 1px solid #b5a57c66;
  color: #dac99f;
  background: transparent;
}
@media (max-width: 600px) {
  .traveler-bar {
    padding: 7px 10px;
    gap: 8px;
  }
  .location-domain,
  .location-accuracy {
    display: none;
  }
  .locate-button {
    flex: 1;
    gap: 8px;
    overflow: hidden;
  }
  .location-text strong {
    font-size: 15px;
    max-width: 100%;
  }
  .connections-button {
    font-size: 10px;
    padding-left: 0;
    gap: 5px;
  }
  .current-danger {
    padding: 3px 5px;
    font-size: 10px;
  }
}
.world-atlas {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
}
.traveler-bar {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
  padding: 20px 16px;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  border-bottom: 0;
  border-right: 1px solid #b5a57c33;
  background: linear-gradient(165deg, #15322f, #0b2028 65%);
}
.atlas-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-bottom: 16px;
  border-bottom: 1px solid #b5a57c33;
  color: #d8c18f;
}
.atlas-heading > span {
  font:
    26px 'KaiTi',
    serif;
}
.atlas-heading strong {
  font:
    20px 'KaiTi',
    serif;
  letter-spacing: 2px;
}
.atlas-heading small {
  width: 100%;
  font-size: 10px;
  letter-spacing: 4px;
  color: #839b90;
}
.locate-button {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: 8px;
  padding: 2px 0;
}
.location-text {
  gap: 6px;
}
.location-text strong {
  font-size: 18px;
}
.location-domain {
  grid-column: 2;
  padding: 0;
  border: 0;
}
.location-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.location-accuracy {
  margin: 0;
  font-size: 11px;
}
.connections-button {
  justify-content: space-between;
  padding: 10px 0;
  border-block: 1px solid #b5a57c25;
}
.connections {
  max-height: 120px;
  padding: 0 0 10px;
  gap: 6px;
}
.index-heading {
  grid-column: 1 / -1;
  display: flex;
  justify-content: space-between;
  color: #bccab9;
  font-size: 12px;
  margin: 5px 0 12px;
}
.index-heading small {
  color: #79968c;
  font-size: 10px;
}
.place-index {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 3px;
}
.sect-index {
  border-top: 1px solid #ccb88026;
  padding-top: 14px;
  margin-top: 12px;
}
.sect-index summary {
  cursor: pointer;
  color: #c8bd99;
  font-size: 12px;
}
.sect-index summary small {
  float: right;
  color: #72918a;
}
.sect-index p {
  font-size: 10px;
  color: #82968c;
  line-height: 1.8;
}
.sect-index button {
  display: flex;
  justify-content: space-between;
  width: 100%;
  padding: 9px 3px;
  border: 0;
  border-bottom: 1px solid #ccb88015;
  background: none;
  color: #b6c6b5;
  text-align: left;
  cursor: pointer;
  font-size: 11px;
}
.sect-index button:hover {
  color: #e0c995;
  background: #c3bc8610;
}
.sect-index button small {
  color: #7e9c96;
  font-size: 9px;
  margin-left: 4px;
}
.place-index button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  border: 1px solid transparent;
  background: transparent;
  padding: 8px 4px;
  color: #a9beb0;
  text-align: left;
  font-size: 12px;
  border-radius: 3px;
}
.place-index button:hover,
.place-index button.current-place {
  background: #b5a57c12;
  border-color: #b5a57c40;
  color: #e1d0a5;
}
.place-index i {
  color: #657f76;
  font-size: 10px;
}
.atlas-reading-hint {
  margin: auto 0 0;
  padding-top: 16px;
  color: #728e83;
  font-size: 10px;
  line-height: 1.9;
}
@media (max-width: 1399px) {
  .world-atlas {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }
  .traveler-bar {
    flex-direction: row;
    align-items: center;
    padding: 6px 12px;
    gap: 14px;
    overflow: visible;
    border-right: 0;
    border-bottom: 1px solid #b5a57c33;
    position: relative;
  }
  .atlas-heading,
  .place-index,
  .sect-index,
  .atlas-reading-hint {
    display: none;
  }
  .locate-button {
    display: flex;
    flex: 1;
  }
  .location-text {
    flex-direction: row;
    align-items: baseline;
    gap: 8px;
  }
  .location-text strong {
    font-size: 16px;
  }
  .location-text small {
    font-size: 10px;
  }
  .location-meta {
    gap: 10px;
  }
  .connections-button {
    padding: 3px 0;
    border: 0;
    gap: 6px;
  }
  .connections {
    position: absolute;
    right: 8px;
    top: 100%;
    z-index: 5;
    max-width: 320px;
    padding: 12px;
    background: #10292c;
    border: 1px solid #b5a57c55;
    box-shadow: 0 8px 22px #03151b88;
  }
}
@media (max-width: 600px) {
  .location-text small,
  .location-domain,
  .location-accuracy {
    display: none;
  }
  .traveler-bar {
    gap: 8px;
  }
  .location-text strong {
    font-size: 15px;
  }
}
